class ClientSession:
    def __init__(self):
        self.protocol_version = None
        self.server_capabilities = None
        self.cached_tools = None

    def on_tools_list_changed_notification(self):
        # Server told us its tools changed; drop the stale cache
        self.cached_tools = None

tool_owner = {}
for client in connected_clients:
    for tool in await client.list_tools():
        tool_owner[tool.name] = client

# Later, when the model wants to call a tool by name
owning_client = tool_owner["send_email"]
result = await owning_client.call_tool("send_email", args)

import asyncio

try:
    result = await asyncio.wait_for(client.call_tool("slow_report", {}), timeout=10)
except asyncio.TimeoutError:
    await client.cancel_request(request_id)
    print("gave up waiting and asked the server to cancel")

clients = {
    "database": MCPClient(db_server_transport),
    "tickets":  MCPClient(ticket_server_transport),
}

